const PET_RANKS=[
{rank:1,level:1,title:'Curious rookie',colour:'#b9cfdb',gear:'scarf'},
{rank:2,level:3,title:'Bright explorer',colour:'#88dcb9',gear:'scout'},
{rank:3,level:5,title:'Clever solver',colour:'#91b7ff',gear:'glasses'},
{rank:4,level:7,title:'Logic ranger',colour:'#7dded3',gear:'scout'},
{rank:5,level:9,title:'Quick tactician',colour:'#eab19b',gear:'glasses'},
{rank:6,level:12,title:'Brilliant strategist',colour:'#c1a0ff',gear:'glasses'},
{rank:7,level:15,title:'Knowledge scholar',colour:'#a8d87d',gear:'professor'},
{rank:8,level:18,title:'Professor paws',colour:'#e5b5ea',gear:'professor'},
{rank:9,level:22,title:'Genius guardian',colour:'#f6d475',gear:'crown'},
{rank:10,level:26,title:'Cosmic mastermind',colour:'#a4f4ee',gear:'cosmic'}
];
const PET_BREEDS={dog:[['Buddy','Labrador','#d9ab72','floppy'],['Scout','Beagle','#b87548','floppy'],['Maple','Cocker Spaniel','#bd8c65','floppy'],['Sunny','Golden Retriever','#e6ba60','floppy'],['Bolt','Schnauzer','#aab4c4','tufted'],['Pixel','Poodle','#d6c8e8','curly'],['Ranger','German Shepherd','#b69167','pointed'],['Quest','Australian Shepherd','#919fb9','tufted'],['Einstein','Border Collie','#49526a','pointed'],['Cosmo','Cosmic Border Collie','#9690d9','pointed']],cat:[['Mochi','Domestic Shorthair','#b6bdcc','pointed'],['Cloud','Ragdoll','#ded4c6','pointed'],['Pebble','British Shorthair','#9facc0','pointed'],['Atlas','Maine Coon','#b38669','tufted'],['Cleo','Burmese','#ac8a79','pointed'],['Nova','Bengal','#d5a063','pointed'],['Sage','Abyssinian','#bf9171','pointed'],['Luna','Siamese','#d9c7a6','pointed'],['Echo','Oriental Shorthair','#9ba9c7','pointed'],['Nebula','Cosmic Siamese','#b1a4e0','pointed']]};
const HEROES=Object.entries(PET_BREEDS).flatMap(([species,breeds])=>breeds.map((b,i)=>({...PET_RANKS[i],id:species+'-'+(i+1),species,name:b[0],breed:b[1],animal:b[1]+' '+species,colour:b[2],ears:b[3],power:PET_RANKS[i].title,hp:4+i,speed:245+4*i,ammo:3+Math.floor(i/3),maxAmmo:9+Math.floor(i/3),damage:1+i,superDamage:2+2*i,shotDelay:.28-i*.01})));
// Load all 40 companions before app.js validates saved selections.
const EXTRA_COMPANIONS={dog:[['Dottie','Dalmatian','#f5f0e3'],['Blizzard','Siberian Husky','#929eac'],['Crumpet','Corgi','#d69a5c'],['Akira','Shiba Inu','#cf8951'],['Dash','Dachshund','#a76d49'],['Bruno','Boxer','#a97652'],['Snow','Samoyed','#f8f2e5'],['Titan','Great Dane','#8d9aa9'],['Swift','Whippet','#bca18a'],['Flutter','Papillon','#f6e9d2']],cat:[['Pearl','Persian','#f2dfcf'],['Sphinx','Sphynx','#d4aa9c'],['Fjord','Norwegian Forest Cat','#9a8c7f'],['Biscuit','Scottish Fold','#c4b7a6'],['Azure','Russian Blue','#8396aa'],['Splash','Turkish Van','#f5eee2'],['Taiga','Siberian','#b0a18b'],['Curly','American Curl','#b7a28e'],['Ember','Somali','#bb8057'],['Orbit','Ocicat','#c4a079']]};
const EXTRA_LEVELS=[28,30,32,34,36,38,41,44,47,50];
const EXTRA_TITLES=['Trailblazer','Star navigator','Brave innovator','Master explorer','Puzzle pioneer','Insight champion','Discovery captain','Brilliant legend','Galaxy guardian','Level 50 legend'];
EXTRA_LEVELS.forEach((level,i)=>PET_RANKS.push({rank:11+i,level,title:EXTRA_TITLES[i],colour:['#8fdcd2','#a8c9ee','#ecc19a','#ebb5d2','#c1b0ec'][i%5],gear:i>=6?'cosmic':'professor'}));
for(const[species,breeds]of Object.entries(EXTRA_COMPANIONS))breeds.forEach((b,i)=>{const n=i+10;HEROES.push({...PET_RANKS[n],id:species+'-'+(n+1),species,name:b[0],breed:b[1],animal:b[1]+' '+species,colour:b[2],ears:'pointed',power:PET_RANKS[n].title,hp:4+n,speed:245+4*n,ammo:3+Math.floor(n/3),maxAmmo:9+Math.floor(n/3),damage:1+n,superDamage:2+2*n,shotDelay:Math.max(.12,.28-n*.008)})});

function playerLevel(){return Math.floor(Math.max(0,Number(profile.xp)||0)/150)+1}
function canSelectAvatar(h){return !!h&&playerLevel()>=h.level}
function ensureAvatar(){if(!canSelectAvatar(HEROES.find(h=>h.id===profile.hero)))profile.hero='dog-1';return HEROES.find(h=>h.id===profile.hero)}
function highestUnlockedRank(){return PET_RANKS.filter(r=>playerLevel()>=r.level).at(-1)}
function petFace(h){const cat=h.species==='cat',dark=h.rank>=9?'#4b4257':'#87624f';return `<g stroke="#332e48" stroke-width="5" stroke-linejoin="round">${cat?`<path d="M56 83L49 30 91 52 133 52 173 30 167 93" fill="${h.colour}"/><path d="M61 59L60 43 82 58M143 58L162 43 159 66" fill="none" stroke="#e9a9b8" stroke-width="6"/>`:h.ears==='floppy'?`<path d="M67 59Q29 43 33 96Q28 132 59 119L83 80M146 58Q184 42 188 93Q195 129 164 121L138 78" fill="${dark}"/>`:`<path d="M62 82L57 29Q81 31 97 64M127 64Q146 28 167 30L165 88" fill="${h.colour}"/>`}<path d="M58 83Q61 49 109 49Q159 48 167 85L163 114Q150 145 111 146Q68 145 57 116Z" fill="${h.colour}"/>${h.rank>=9&&h.species==='dog'?'<path d="M97 52L121 52 133 97 111 128 86 96Z" fill="#f4e8d2" stroke="none"/>':''}${h.rank===2&&h.species==='dog'?'<path d="M61 80Q66 53 92 55L91 99 59 105Z" fill="#f0debd" stroke="none"/>':''}${h.species==='cat'&&h.gear==='professor'?'<path d="M70 68l10 6M89 58l9 9M137 61l-8 9M150 79l-12 3" stroke="#74503b" stroke-width="6"/>':''}${h.ears==='curly'?'<path d="M63 66Q50 44 72 42Q77 20 96 39Q114 15 127 39Q150 21 155 46Q177 42 167 70" fill="#e4d9f2"/>':''}<ellipse cx="111" cy="118" rx="27" ry="20" fill="#f4dfc7" stroke="none"/><ellipse cx="84" cy="94" rx="5" ry="8" fill="#29263c" stroke="none"/><ellipse cx="139" cy="94" rx="5" ry="8" fill="#29263c" stroke="none"/><path d="M102 111Q111 105 120 111L111 119Z" fill="#493747" stroke-width="2"/><path d="M111 119V125Q101 135 96 126M111 125Q121 135 128 126" fill="none" stroke-width="3"/>${cat?'<path d="M81 117L45 111M81 126L43 129M141 117L178 111M141 126L180 129" stroke="#e9dcc7" stroke-width="3"/>':''}${h.rank>=3?'<g fill="#ffffff15" stroke="#33344d" stroke-width="4"><rect x="65" y="81" width="37" height="28" rx="10"/><rect x="121" y="81" width="37" height="28" rx="10"/><path d="M102 91Q111 85 121 91" fill="none"/></g>':''}${h.gear==='professor'?'<path d="M64 49L111 31 160 49 111 64Z" fill="#70628e"/><path d="M160 49V77" stroke="#f4d471" stroke-width="3"/>':''}${h.rank>=9?'<path d="M78 50L70 21 94 31 111 10 128 31 152 21 144 50Z" fill="#efd16f" stroke="#805741" stroke-width="4"/><path d="M104 34L111 24 118 34 111 43Z" fill="#a27ce9" stroke="none"/>':''}</g>`}
function heroSVG(id=profile.hero,extra=''){const h=HEROES.find(h=>h.id===id)||HEROES[0];return `<svg viewBox="0 0 220 250" ${extra} aria-label="${h.name}, ${h.breed}, ${h.title}" role="img"><ellipse cx="111" cy="230" rx="66" ry="13" fill="#11112e33"/><path d="M144 178Q211 152 192 197Q182 217 151 208" fill="none" stroke="${h.colour}" stroke-width="17" stroke-linecap="round"/><path d="M72 191L70 222 94 222 102 190M125 190L129 222 154 222 148 189" fill="#44445e" stroke="#302c45" stroke-width="5"/><path d="M72 136Q112 122 151 138L166 193Q112 214 57 193Z" fill="#535b78" stroke="#302c45" stroke-width="5"/><path d="M64 152L43 170 51 190 78 172M153 151L179 169 168 189 143 171" fill="${h.colour}" stroke="#302c45" stroke-width="5"/><path d="M72 142L111 168 152 141 135 173 111 182 88 173Z" fill="${h.colour==='dog'?'#bce56c':h.rank>=9?'#f6d475':PET_RANKS[h.rank-1].colour}"/><path d="M64 188L158 188" stroke="#302c45" stroke-width="10"/><rect x="101" y="182" width="20" height="16" rx="3" fill="${PET_RANKS[h.rank-1].colour}"/>${petFace(h)}<path d="M180 161l18-8 9 27-20 9-12-12Z" fill="#9de3e0" stroke="#37394f" stroke-width="4"/></svg>`}
function petPortrait(h){return `<svg viewBox="25 0 175 160" aria-hidden="true">${petFace(h)}</svg>`}
let petTab='dog',unlockNoticeRank=1;
function selectAvatar(id){const h=HEROES.find(h=>h.id===id);if(!canSelectAvatar(h))return false;profile.hero=h.id;petTab=h.species;save();return true}
function heroes(){const selected=ensureAvatar(),level=playerLevel(),next=PET_RANKS.find(r=>r.level>level);return `${heading('Your companion. Your climb.','Earn knowledge. Unlock brighter companions. Choose your dog or cat.')}${breedLineup(petTab)}<section class="pet-overview"><div class="equipped-pet">${heroSVG(selected.id)}<div><span class="tag">YOUR AVATAR · RANK ${selected.rank}</span><h2>${selected.name}</h2><p>${selected.breed} · ${selected.title}</p><b>Level ${level} · ${profile.xp} XP</b><div class="pet-stats"><span>♥ ${selected.hp} life</span><span>ϟ ${selected.damage} attack</span><span>✦ ${selected.superDamage} super</span></div></div></div><div class="next-unlock"><span class="eyebrow">${next?'YOUR NEXT COMPANIONS':'TOP RANK UNLOCKED'}</span><h3>${next?next.title:'Cosmic mastermind'}</h3><p>${next?`Reach level ${next.level} to unlock a new dog and cat. <b>${(next.level-1)*150-profile.xp} XP to go.</b>`:'Every companion is now available. Keep learning and exploring!'}</p><div class="track" style="--accent:var(--lime)"><span style="width:${next?Math.min(100,profile.xp/((next.level-1)*150)*100):100}%"></span></div></div></section><div class="pet-tabs" role="group" aria-label="Choose avatar species"><button data-pet-tab="dog" aria-pressed="${petTab==='dog'}" class="${petTab==='dog'?'active':''}">🐾 Dogs <span>10 companions</span></button><button data-pet-tab="cat" aria-pressed="${petTab==='cat'}" class="${petTab==='cat'?'active':''}">🐈 Cats <span>10 companions</span></button></div><div class="section-title"><div><h2>The knowledge ladder</h2><p>Genius at the top. Start your adventure at the bottom.</p></div><span class="count">HIGHEST RANK FIRST ↓</span></div><div class="pet-ladder">${HEROES.filter(h=>h.species===petTab).reverse().map(h=>{const unlocked=canSelectAvatar(h),active=h.id===selected.id;return `<article class="pet-rung ${unlocked?'unlocked':'locked'} ${active?'equipped':''}" style="--rank-colour:${PET_RANKS[h.rank-1].colour}"><div class="rank-marker"><strong>${h.rank}</strong><span>RANK</span></div><div class="rung-art">${heroSVG(h.id)}</div><div class="rung-copy"><span class="tag">${h.title.toUpperCase()}</span><h3>${h.name} <small>${h.breed}</small></h3><p>${unlocked?'Unlocked — ready for your next quest.':`Reach level ${h.level} · ${(h.level-1)*150} total XP`}</p><div class="pet-stats"><span>♥ ${h.hp} life</span><span>ϟ ${h.damage} attack</span><span>✦ ${h.superDamage} super</span></div></div><button class="${active?'primary':'secondary'}" data-hero="${h.id}" ${unlocked?'':'disabled'}>${active?'Selected ✓':unlocked?'Choose '+h.name:'🔒 Level '+h.level}</button></article>`}).join('')}</div><div class="info-panel"><h2>Grow your knowledge, grow your crew.</h2><p>Both starter pets are available at level 1. New dog and cat pairs unlock at levels 3, 5, 7, 9, 12, 15, 18, 22 and 26. Higher ranks gain life, attack power, super power and energy capacity. Monster health, damage and speed scale with the avatar you equip. Choose any unlocked companion for its matching rank challenge.</p></div>`}
